import {
    RESET_REDUX,
    CREATE_MANUFACTURER_VARIATION,
    CREATE_MANUFACTURER_VARIATION_FAILED,
    CREATE_MANUFACTURER_VARIATION_SUCCESS,
    UPDATE_MANUFACTURER_VARIATION,
    UPDATE_MANUFACTURER_VARIATION_FAILED,
    UPDATE_MANUFACTURER_VARIATION_SUCCESS,
    SEARCH_MANUFACTURER_VARIATIONS_SUCCESS,
    GET_MANUFACTURER_VARIATIONS_SUCCESS,
    SEARCH_MANUFACTURER_VARIATIONS_FAILED,
    GET_MANUFACTURER_VARIATION_DETAILS_SUCCESS,
    GET_MANUFACTURER_VARIATION_DETAILS,
    GET_MANUFACTURER_VARIATION_DETAILS_FAILED,
    GET_MANUFACTURER_BY_ID_VARIATIONS,
    GET_MANUFACTURER_VARIATIONS,
    GET_MANUFACTURER_BY_ID_VARIATIONS_SUCCESS,
    GET_MANUFACTURER_BY_ID_VARIATIONS_FAILED,
    SEARCH_MANUFACTURER_VARIATIONS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS,
    GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED,
    SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS,
} from './constants';

const INIT_STATE = {
    loading: false,
    errors: [],
    success: false,
    updated: false,
    manufacturerVariations: [],
    manufacturerVariation: null,
    count: 0,
    next: null,
    previous: null,
    message: null,
};

const Variations = (state = INIT_STATE, action) => {
    switch (action.type) {
        case RESET_REDUX:
            return { ...state, updated: false, loading: false, success: false, message: null };

        case CREATE_MANUFACTURER_VARIATION:
        case UPDATE_MANUFACTURER_VARIATION:
        case GET_MANUFACTURER_VARIATION_DETAILS:
        case GET_MANUFACTURER_BY_ID_VARIATIONS:
        case GET_MANUFACTURER_VARIATIONS:
        case SEARCH_MANUFACTURER_VARIATIONS:
        case GET_MANUFACTURER_AND_PRODUCT_VARIATIONS:
        case SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS:
            return {
                ...state,
                manufacturerVariation: null,
                manufacturerVariations: [],
                success: false,
                error: null,
                loading: true,
                updated: false,
            };

        case CREATE_MANUFACTURER_VARIATION_SUCCESS:
        case UPDATE_MANUFACTURER_VARIATION_SUCCESS:
        case GET_MANUFACTURER_VARIATION_DETAILS_SUCCESS:
            return {
                ...state,
                manufacturerVariation: action.payload,
                loading: false,
                updated: true,
            };

        case GET_MANUFACTURER_VARIATIONS_SUCCESS:
        case GET_MANUFACTURER_BY_ID_VARIATIONS_SUCCESS:
        case SEARCH_MANUFACTURER_VARIATIONS_SUCCESS:
        case GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS:
        case SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_SUCCESS:
            console.log('am here', action.payload.results);
            return {
                ...state,
                manufacturerVariations: action.payload.results,
                count: action.payload.count,
                next: action.payload.next,
                previous: action.payload.previous,
                loading: false,
            };

        case GET_MANUFACTURER_BY_ID_VARIATIONS_FAILED:
        case SEARCH_MANUFACTURER_VARIATIONS_FAILED:
        case UPDATE_MANUFACTURER_VARIATION_FAILED:
        case CREATE_MANUFACTURER_VARIATION_FAILED:
        case GET_MANUFACTURER_VARIATION_DETAILS_FAILED:
        case GET_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED:
        case SEARCH_MANUFACTURER_AND_PRODUCT_VARIATIONS_FAILED:
            return {
                ...state,
                error: action.payload.message,
                errors: action.payload.errors,
                manufacturerVariation: null,
                manufacturerVariations: null,
                success: false,
                loading: false,
            };

        default:
            return { ...state };
    }
};

export default Variations;
